/* From Uiverse.io by vk-uiux - Source: vk-uiux - Tags: animation, loader, spinner, book, animated, css, css effect */
.__UIV_SCOPE__ .loader {
  position: relative;
  width: 33px;
  height: 33px;
  perspective: 67px;
}

.__UIV_SCOPE__ .loader div {
  width: 100%;
  height: 100%;
  background: #fff;
  position: absolute;
  left: 50%;
  transform-origin: left;
  animation: loader 2s infinite;
}

.__UIV_SCOPE__ .loader div:nth-child(1) {
  animation-delay: 0.15s;
}

.__UIV_SCOPE__ .loader div:nth-child(2) {
  animation-delay: 0.3s;
}

.__UIV_SCOPE__ .loader div:nth-child(3) {
  animation-delay: 0.45s;
}

.__UIV_SCOPE__ .loader div:nth-child(4) {
  animation-delay: 0.6s;
}

.__UIV_SCOPE__ .loader div:nth-child(5) {
  animation-delay: 0.75s;
}

@keyframes loader {
  0% {
    transform: rotateY(0deg);
  }

  50%, 80% {
    transform: rotateY(-180deg);
  }

  90%, 100% {
    opacity: 0;
    transform: rotateY(-180deg);
  }
}
